  .clm-calc-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 8px;
    margin-bottom: 12px;
  }

  .clm-calc-card {
    padding: 8px 10px;
  }

  .clm-calc-label {
    font-size: 9px;
    margin-bottom: 4px;
  }

  .clm-calc-value {
    font-size: 16px;
  }

  .clm-calc-sub {
    font-size: 10px;
    margin-top: 2px;
  }

  .clm-alert {
    padding: 10px 12px;
    gap: 10px;
    font-size: 12px;
  }

  .clm-alert-icon {
    font-size: 16px;
  }

  .clm-hierarchy-strip {
    padding: 10px 12px;
    margin-top: 12px;
    border-radius: 5px;
  }

  .clm-hierarchy-title {
    font-size: 9px;
    margin-bottom: 6px;
  }

  .clm-hierarchy-node {
    padding: 3px 0;
    font-size: 11px;
    gap: 6px;
  }

  .clm-hierarchy-level {
    font-size: 8px;
    min-width: 40px;
  }

  .clm-hierarchy-name {
    font-size: 11px;
  }

  .clm-hierarchy-limit {
    font-size: 11px;
  }

  .clm-actions {
    padding: 12px 14px;
    gap: 8px;
    flex-direction: column;
  }

  .clm-btn {
    width: 100%;
    padding: 10px 16px;
    font-size: 13px;
    min-width: unset;
  }

  .clm-success-panel {
    padding: 40px 16px;
  }

  .clm-success-icon {
    width: 48px;
    height: 48px;
    font-size: 22px;
    margin-bottom: 16px;
  }

  .clm-success-panel h3 {
    font-size: 16px;
    margin-bottom: 10px;
  }

  .clm-success-panel p {
    font-size: 12px;
    margin-bottom: 16px;
    line-height: 1.5;
  }

  .clm-deviation-note {
    font-size: 11px;
    padding: 10px 12px;
  }

  /* Multi-segment mobile */
  .clm-ms-toggle-label {
    font-size: 12px;
  }

  .clm-ms-method-row {
    padding: 12px 12px;
  }

  .clm-ms-method-label {
    font-size: 10px;
    margin-bottom: 8px;
  }

  .clm-ms-method-options {
    gap: 8px;
    flex-direction: column;
  }

  .clm-ms-radio {
    width: 100%;
    padding: 10px 12px;
    min-width: unset;
    font-size: 12px;
  }

  .clm-ms-radio-label strong {
    font-size: 12px;
  }

  .clm-ms-radio-label small {
    font-size: 10px;
  }

  .clm-ms-table-header {
    padding: 8px 10px;
    font-size: 9px;
  }

  .clm-ms-table-row {
    padding: 8px 10px;
    flex-direction: column;
    gap: 8px;
  }

  .clm-ms-col-seg {
    flex: 1;
  }

  .clm-ms-col-num {
    text-align: left;
  }

  .clm-ms-seg-name {
    font-size: 12px;
  }

  .clm-ms-calc {
    font-size: 11px;
  }

  .clm-ms-input {
    padding: 6px 8px;
    font-size: 11px;
    text-align: left;
  }

  .clm-ms-totals-row {
    padding: 10px 10px;
    font-size: 11px;
    flex-direction: column;
  }

  .clm-ms-alert {
    padding: 10px 10px;
    font-size: 11px;
  }

  .clm-ms-hold-info {
    padding: 14px 12px;
    gap: 10px;
    flex-direction: column;
  }

  .clm-ms-hold-icon {
    font-size: 24px;
  }

  .clm-ms-hold-info strong {
    font-size: 13px;
    margin-bottom: 6px;
  }

  .clm-ms-hold-info p {
    font-size: 11px;
    line-height: 1.5;
  }

  /* TCL mobile */
  .clm-tcl-existing {
    padding: 8px 10px;
    margin-bottom: 10px;
    border-radius: 4px;
  }

  .clm-tcl-existing-title {
    font-size: 9px;
    margin-bottom: 6px;
  }

  .clm-tcl-existing-row {
    gap: 6px;
    padding: 3px 0;
    font-size: 11px;
    flex-wrap: wrap;
  }

  .clm-tcl-existing-seg {
    min-width: 45px;
    font-size: 11px;
  }

  .clm-tcl-existing-amt {
    font-size: 11px;
  }

  .clm-tcl-existing-perm {
    font-size: 10px;
  }

  .clm-tcl-existing-date {
    margin-left: auto;
    font-size: 10px;
  }

  .clm-tcl-toggle-label {
    font-size: 12px;
  }

  .clm-tcl-panel {
    margin-top: 10px;
    border-radius: 5px;
  }

  .clm-tcl-info-box {
    padding: 10px 12px;
    gap: 8px;
  }

  .clm-tcl-info-icon {
    font-size: 16px;
  }

  .clm-tcl-info-text {
    font-size: 11px;
    line-height: 1.5;
  }

  .clm-tcl-panel .clm-row {
    padding: 12px 10px;
    margin-bottom: 8px;
  }

  .clm-tcl-panel .clm-row:last-of-type {
    margin-bottom: 0;
  }

  .clm-tcl-calc-strip {
    padding: 10px 10px;
    flex-direction: column;
    gap: 8px;
  }

  .clm-tcl-calc-item {
    padding: 8px 0;
    gap: 3px;
  }

  .clm-tcl-calc-item:first-child {
    padding-left: 0;
  }

  .clm-tcl-calc-label {
    font-size: 9px;
  }

  .clm-tcl-calc-val {
    font-size: 14px;
  }

  .clm-tcl-calc-arrow {
    display: none;
  }

  .clm-tcl-warning {
    padding: 10px 10px;
    font-size: 11px;
  }

  /* Inner padding for mobile */
  .clm-header,
  .clm-section,
  .clm-calc-panel,
  .clm-actions,
  .clm-success-panel {
    padding-left: 14px;
    padding-right: 14px;
  }
}

/* ============================================================
   EXTRA SMALL DEVICES — 360px
   ============================================================ */

@media (max-width: 360px) {
  .clm-header {
    padding: 12px 12px;
  }

  .clm-title {
    font-size: 15px;
  }

  .clm-subtitle {
    font-size: 10px;
  }

  .clm-request-badge {
    padding: 2px 8px;
    font-size: 10px;
  }

  .clm-section {
    padding: 14px 12px;
  }

  .clm-section-title {
    font-size: 11px;
    margin-bottom: 12px;
  }

  .clm-section-num {
    width: 18px;
    height: 18px;
    font-size: 9px;
  }

  .clm-field label {
    font-size: 11px;
  }

  .clm-input,
  .clm-textarea {
    font-size: 12px;
    padding: 6px 8px;
  }

  .clm-textarea {
    min-height: 60px;
  }

  .clm-input-btn {
    padding: 6px 10px;
    font-size: 11px;
  }

  .clm-customer-strip {
    gap: 4px;
    padding: 8px 10px;
  }

  .clm-strip-label {
    font-size: 8px;
  }

  .clm-strip-value {
    font-size: 10px;
  }

  .clm-calc-panel {
    padding: 12px 12px;
  }

  .clm-calc-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 6px;
  }

  .clm-calc-card {
    padding: 6px 8px;
  }

  .clm-calc-label {
    font-size: 8px;
  }

  .clm-calc-value {
    font-size: 14px;
  }

  .clm-alert {
    padding: 8px 10px;
    font-size: 11px;
  }

  .clm-hierarchy-strip {
    padding: 8px 10px;
  }

  .clm-hierarchy-title {
    font-size: 8px;
  }

  .clm-hierarchy-node {
    font-size: 10px;
  }

  .clm-hierarchy-level {
    font-size: 7px;
    min-width: 35px;
  }

  .clm-actions {
    padding: 10px 12px;
    gap: 6px;
  }

  .clm-btn {
    padding: 8px 12px;
    font-size: 12px;
  }

  .clm-success-panel {
    padding: 32px 12px;
  }

  .clm-success-icon {
    width: 40px;
    height: 40px;
    font-size: 18px;
    margin-bottom: 12px;
  }

  .clm-success-panel h3 {
    font-size: 14px;
    margin-bottom: 8px;
  }

  .clm-success-panel p {
    font-size: 11px;
  }

  /* Inner padding for extra small */
  .clm-header,
  .clm-section,
  .clm-calc-panel,
  .clm-actions,
  .clm-success-panel {
    padding-left: 12px;
    padding-right: 12px;
  }
}

/* ============================================================
   DESKTOP BREAKPOINT — 1024px+
   ============================================================ */

@media (min-width: 1024px) {
  .clm-header,
  .clm-section,
  .clm-calc-panel,
  .clm-actions,
  .clm-success-panel {
    padding-left: 28px;
    padding-right: 28px;
  }

  .clm-row {
    gap: 24px;
  }

  .clm-field {
    min-width: 220px;
  }

  .clm-actions {
    justify-content: flex-end;
  }

  .clm-btn {
    flex: 0 1 auto;
  }

  .clm-calc-grid {
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  }
}

/* ============================================================
   ULTRA WIDE — 1600px+
   ============================================================ */

@media (min-width: 1600px) {
  .clm-header,
  .clm-section,
  .clm-calc-panel,
  .clm-actions,
  .clm-success-panel {
    padding-left: 48px;
    padding-right: 48px;
  }

  .clm-row {
    gap: 32px;
  }

  .clm-field {
    min-width: 250px;
  }

  .clm-calc-grid {
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 16px;
  }
}

sp_widget.script:
(function() {

    var action = input && input.action;

    // ── searchCustomers (by PAN or Name, filtered by TSH) ─────
    if (action === 'searchCustomers') {

        var searchTerm = (input.searchTerm || '').trim();
        if (searchTerm.length < 3) { 
            data.customers = []; 
            return; 
        }

        // Get current user's TSH record
        var currentUserID = gs.getUserID();
      var tshGr = new GlideRecord('x_birl3_clm_tsh');
tshGr.addQuery('name', gs.getUserID()); // ✅ correct
tshGr.setLimit(1);
tshGr.query();

var tshSysId = '';
if (tshGr.next()) {
    tshSysId = tshGr.sys_id + '';
}

        // If no TSH record found, return empty
        if (!tshSysId) {
            data.customers = [];
            data.error = 'No TSH record found for current user';
            return;
        }

        // Search customers by PAN or Name, filtered by TSH
        var custGr = new GlideRecord('x_birl3_clm_clm_customer_master1');
        custGr.addQuery('tsh', tshSysId); // Filter by TSH

        // Search by PAN or Customer Name
        var qc = custGr.addQuery('pan', 'CONTAINS', searchTerm);
qc.addOrCondition('customer_name', 'CONTAINS', input.searchTerm);

        custGr.orderBy('customer_name');
        custGr.query();

        var customers = [];
        while (custGr.next()) {

            // Get vintage days
            var vintageDays = 0;
            var fos = custGr.first_order_date + '';
            if (fos && fos !== '' && fos !== 'null') {
                var fd = new GlideDate(); 
                fd.setValue(fos);
                var td = new GlideDate();
                var dd = Math.floor((td.getNumericValue() - fd.getNumericValue()) / (1000 * 60 * 60 * 24));
                vintageDays = dd > 0 ? dd : 0;
            }

            // Get outstanding
            var outstanding = 0;
            var agGr = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
            agGr.addQuery('customer', custGr.sys_id + '');
            agGr.orderByDesc('snapshot_month');
            agGr.setLimit(1);
            agGr.query();
            if (agGr.next()) outstanding = parseFloat(agGr.total_outstanding) || 0;

            customers.push({
                sys_id:               custGr.sys_id + '',
                customer_name:        custGr.customer_name + '',
                customer_code_sap:    custGr.customer_code_sap + '',
                customer_type:        custGr.customer_type + '',
                segment:              custGr.segment + '',
                zone:                 custGr.zone + '',
                region:               custGr.region + '',
                pan:                  custGr.pan + '',
                cg2_code:             custGr.cg2_code + '',
                constitution:         custGr.constitution + '',
                is_listed:            custGr.is_listed + '' === 'true',
                vintage_days:         vintageDays,
                current_sd:           parseFloat(custGr.current_sd_amount)    || 0,
                current_credit_limit: parseFloat(custGr.current_credit_limit) || 0,
                avg_monthly_sales:    parseFloat(custGr.avg_monthly_sales_mt) || 0,
                order_rate:           7000,
                outstanding:          outstanding
            });
        }

        data.customers = customers;
    }

    // ── loadSites (for Non-Trade customers) ───────────────────
    else if (action === 'loadSites') {

        var custSysId = input.customerSysId || '';
        var pan       = input.pan || '';

        // Get current user's TSH record to find depot
        var currentUserID = gs.getUserID();
       var tshGr = new GlideRecord('x_birl3_clm_tsh');
tshGr.addQuery('user', gs.getUserID()); // <-- IMPORTANT (create this field if not present)
tshGr.setLimit(1);
tshGr.query();
        tshGr.setLimit(1);
        tshGr.query();

        var depot = '';
        if (tshGr.next()) {
            depot = tshGr.depot + '';
        }

        // Load sites for this customer (same PAN) under this depot
        var sites = [];

        // Get all customers with same PAN under this depot
        var custGr2 = new GlideRecord('x_birl3_clm_clm_customer_master1');
        custGr2.addQuery('pan', pan);
        custGr2.addQuery('customer_type', 'Non-Trade');
        custGr2.query();

        while (custGr2.next()) {
            // Get outstanding for this site
            var outstanding = 0;
            var agGr2 = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
            agGr2.addQuery('customer', custGr2.sys_id + '');
            agGr2.orderByDesc('snapshot_month');
            agGr2.setLimit(1);
            agGr2.query();
            if (agGr2.next()) outstanding = parseFloat(agGr2.total_outstanding) || 0;

            sites.push({
                site_code:         custGr2.customer_code_sap + '',
                depot:             depot,
                location:          custGr2.region + ' - ' + custGr2.zone,
                current_limit:     parseFloat(custGr2.current_credit_limit) || 0,
                outstanding:       outstanding,
                project_potential: 0,
                monthly_volume:    0,
                requested_limit:   0
            });
        }

        data.sites = sites;
    }

    // ── calculate (Trade only - same as before) ──────────────
    else if (action === 'calculate') {

        var custSysId = input.customerSysId || '';
        var req       = parseFloat(input.requestedLimit)  || 0;
        var sd        = parseFloat(input.activeSD)        || 0;
        var os        = parseFloat(input.outstanding)     || 0;
        var avg       = parseFloat(input.avgMonthlySales) || 0;
        var segment   = input.segment    || 'Cement';
        var cg2Code   = input.cg2Code    || '';
        var vin       = parseInt(input.vintageDays) || 0;

        // Aging
        var total=0, safe=0, warning=0, critical=0, toxic=0, mCount=0;
        var salesLast=0, salesPrev=0;

        var agGr2 = new GlideRecord('x_birl3_clm_clm_aging_snapshot');
        agGr2.addQuery('customer', custSysId);
        agGr2.orderByDesc('snapshot_month');
        agGr2.setLimit(6);
        agGr2.query();

        while (agGr2.next()) {
            mCount++;
            total    += parseFloat(agGr2.total_outstanding)   || 0;
            safe     += (parseFloat(agGr2.bucket_0_30_days)   || 0)
                      + (parseFloat(agGr2.bucket_31_45_days)  || 0)
                      + (parseFloat(agGr2.bucket_46_60_days)  || 0);
            warning  += parseFloat(agGr2.bucket_61_75_days)   || 0;
            critical += parseFloat(agGr2.bucket_76_90_days)   || 0;
            toxic    += (parseFloat(agGr2.bucket_91_120_days) || 0)
                      + (parseFloat(agGr2.bucket_gt120_days)  || 0);
            if (mCount === 1) {
                salesLast = parseFloat(agGr2.sales_current_month) || 0;
                salesPrev = parseFloat(agGr2.sales_prev_month)    || 0;
            }
        }

        // Aging rating
        var agRating = 'A';
        if (total > 0) {
            var sp = safe  / total;
            var tp = (critical + toxic) / total;
            if      (sp >= 0.80 && tp <= 0.10) agRating = 'A';
            else if (sp >= 0.60 && tp <= 0.20) agRating = 'B';
            else                                agRating = 'C';
        }

        // NOD
        var nod = 0;
        var avg2M = (salesLast + salesPrev) / 2;
        if (vin <= 60) {
            if (avg > 0) nod = Math.ceil((os / avg) * Math.min(vin, 60));
        } else {
            if (avg2M > 0) nod = Math.round((os / avg2M) * 30);
        }

        // Multiplier
        var multiplier = 1;
        if (vin < 90) {
            multiplier = 1;
        } else if (vin < 180) {
            multiplier = (nod < 15 && avg > 1000) ? 2 : 1;
        } else {
            var mGr = new GlideRecord('x_birl3_clm_clm_multiplier');
            mGr.addQuery('cg2_code',  cg2Code);
            mGr.addQuery('segment',   segment);
            mGr.addQuery('is_active', true);
            mGr.setLimit(1);
            mGr.query();
            if (mGr.next()) multiplier = parseInt(mGr.multiplier) || 1;
            else {
                if      (cg2Code === 'CG2_A' || cg2Code === 'PMNT_GOOD') multiplier = 4;
                else if (cg2Code === 'CG2_B')                              multiplier = 2;
                else                                                        multiplier = 1;
            }
        }

        var netExp   = Math.max(0, req - sd);
        var maxAllw  = sd * multiplier;
        var implMult = sd > 0 ? req / sd : 0;
        var isDev    = req > maxAllw;

        // Approval routing
        var router   = new CLMApprovalRouter();
        var approver = router.getApprover(segment, 'Trade', netExp, nod, isDev, implMult, vin);

        data.calc = {
            multiplier:   multiplier,
            maxAllowable: maxAllw  / 100000,
            netExposure:  netExp   / 100000,
            impliedMult:  implMult,
            isDeviation:  isDev,
            nod:          nod,
            agingRating:  agRating,
            approverRole: approver.role,
            escalated:    approver.escalated || false,
            reason:       approver.reason    || ''
        };
    }

    // ── saveDraft ─────────────────────────────────────────────
    else if (action === 'saveDraft') {
        var f  = input.form;
        var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        if (f.draftSysId) gr.get(f.draftSysId); 
        else gr.initialize();

        gr.customer_type           = f.customerType;
        gr.segment                 = f.segment;
        gr.customer                = f.customerSysId;
        gr.requested_limit         = f.requestedLimit;
        gr.active_sd               = f.activeSD;
        gr.outstanding_amount      = f.outstanding;
        gr.avg_monthly_sales       = f.avgMonthlySales;
        gr.sales_last_month        = f.salesLastMonth;
        gr.sales_prev_month        = f.salesPrevMonth;
        gr.cheque_bounces_12m      = f.chequeBounces;
        gr.market_perception       = f.marketPerception;
        gr.business_justification  = f.justification;
        gr.deviation_justification = f.deviationJustification;
        gr.state                   = 'Draft';
        gr.initiator               = gs.getUserID();

        var sysId = f.draftSysId ? gr.update() : gr.insert();
        var gr2 = new GlideRecord('x_birl3_clm_clm_new_credit_request');
        gr2.get(sysId);
        data.sysId  = sysId;
        data.number = gr2.request_number + '';
    }

    // ── submit ────────────────────────────────────────────────
    else if (action === 'submit') {
        var f = input.form;
        try {
            var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
            gr.initialize();
            gr.customer_type           = f.customerType;
            gr.segment                 = f.segment;
            gr.customer                = f.customerSysId;
            gr.requested_limit         = f.requestedLimit;
            gr.active_sd               = f.activeSD;
            gr.outstanding_amount      = f.outstanding;
            gr.avg_monthly_sales       = f.avgMonthlySales;
            gr.sales_last_month        = f.salesLastMonth;
            gr.sales_prev_month        = f.salesPrevMonth;
            gr.cheque_bounces_12m      = f.chequeBounces;
            gr.market_perception       = f.marketPerception;
            gr.business_justification  = f.justification;
            gr.deviation_justification = f.deviationJustification;
            gr.initiator               = gs.getUserID();
            gr.state                   = 'Submitted';

            // Store sites data if Non-Trade
            if (f.sites && f.sites.length > 0) {
                gr.u_sites_json = JSON.stringify(f.sites);
            }

            var sysId = gr.insert();
            if (!sysId) { 
                data.success = false; 
                data.error = 'Failed to create request.'; 
                return; 
            }

            var result = new GlideRecord('x_birl3_clm_clm_new_credit_request');
            result.get(sysId);
            data.success       = true;
            data.requestNumber = result.request_number + '';
            data.approverRole  = result.required_approver_level + '';
            data.isDeviation   = result.is_deviation + '' === 'true';
            data.sysId         = sysId;

        } catch(e) {
            data.success = false;
            data.error   = 'Error: ' + e.message;
        }
    }

})();
